<script setup lang="tsx">
import type { WatchStopHandle } from "vue";
import { onBeforeUnmount, onMounted, ref, watch } from "vue";
import { LocationQuery, useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, GetEllipsisText, ShowErrorTips, ShowTextTipsInfo } from "@/util/tips";
import { GetContestProblemIndexStr, GetContestRank, GetContestReplayList, ParseContestReplay } from "@/apis/contest.ts";
import { JudgeStatus } from "@/apis/judge.ts";
import { GetSecondFromDuration, GetTimeStringBySeconds } from "@/time/library.ts";
import { StarIcon, StarFilledIcon } from "tdesign-icons-vue-next";
import { useContestStore } from "@/stores/contest.ts";
import { GetAvatarUrl } from "@/util/avatar.ts";
import type { TableRowData, TNodeReturnValue } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import type { ContestRank, ContestRankProblem, ContestRankView, ContestReplay, ContestReplayRaw } from "@/types/contest.ts";
import { formatReplaySourceTooltip, isReplayRow, replayRankKey, replayRankTiebreak } from "@/views/contest/contest-replay-common.ts";
import { saveAs } from "file-saver";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const contestStore = useContestStore();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

let viewActive = false;
let watchHandle: WatchStopHandle | null = null;
let contestId = 0;
let contestStartTime = null as Date | null;
let contestEndTime = null as Date | null;
let lockRankDurationSeconds = 0;
let contestNames = {} as Record<number, string>;
const progressValue = ref(0);
const progressMax = ref(0);
const onlyShowStarMembers = ref(false);
const enableAnimation = ref(true);
const autoRefresh = ref(true);
const autoScroll = ref(false);
let fetchTimer: ReturnType<typeof setInterval> | null = null;
let updateProgressTimer: ReturnType<typeof setInterval> | null = null;

let scrollTimer: ReturnType<typeof setInterval> | null = null;
const scrollSpeed = 1; // 每次滚动的像素数
const scrollInterval = 20; // 每次滚动间隔（毫秒）

let currentPage = 1;
let currentPageSize = 50;
const pagination = ref({
  current: currentPage,
  pageSize: currentPageSize,
  defaultCurrent: 1,
  defaultPageSize: 50,
  total: 0,
  pageSizeOptions: [50, 100, 1000],
});

const isUserBeStar = (userId: number) => {
  return contestStore && contestStore.isStarMember(contestId, userId);
};

const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  pagination.value = { ...pagination.value, current: pageInfo.current, pageSize: pageInfo.pageSize };
  // 更新 URL 查询参数
  await router.push({
    query: { ...route.query, page: pageInfo.current, page_size: pageInfo.pageSize },
  });
};

const getDurationText = (duration: number) => {
  if (duration === undefined || duration === null) {
    return "-";
  }
  const hours = Math.floor(duration / 3600)
    .toString()
    .padStart(2, "0");
  const minutes = Math.floor((duration % 3600) / 60)
    .toString()
    .padStart(2, "0");
  const seconds = (duration % 60).toFixed(0).toString().padStart(2, "0");
  return `${hours}:${minutes}:${seconds}`;
};

const progressMarks = ref({} as Record<number, string | TNodeReturnValue>);
type ProblemFirstAcRecord = {
  key: string;
  ac: number;
};
let problemFirstAcRecords = {
  key: "",
  ac: -1,
} as Record<number, ProblemFirstAcRecord>;

// 说明：tdesign 的 BaseTableCol<T> 是递归类型（children?: BaseTableCol<T>[]），本页会动态推入问题列、cell/attrs 返回 JSX 与样式，
// 直接标注会触发 TS2589（Type instantiation is excessively deep），故按其字段构造一个非递归的等价列类型
type ContestRankColumn = {
  title?: string | (() => TNodeReturnValue);
  colKey?: string;
  align?: "left" | "right" | "center";
  fixed?: "left" | "right";
  attrs?: (data: CellParams<TableRowData>) => { style?: Record<string, string> };
  cell?: (_h: unknown, data: CellParams<TableRowData>) => TNodeReturnValue;
};

const listColumns1: ContestRankColumn[] = [
  {
    title: "Rank",
    colKey: "rank",
    align: "center",
    fixed: "left",
  },
  {
    title: "昵称",
    colKey: "nickname",
    fixed: "left",
    attrs: (data: CellParams<TableRowData>) => {
      const row = data.row as ContestRankView;
      let style = {};
      // 回放行不参与收藏，底色高亮只作用于真人行
      if (!isReplayRow(row) && isUserBeStar(row.userId)) {
        style = { backgroundColor: "rgba(255,165,30,0.5)" };
      }
      return {
        style: style,
      };
    },
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const row = data.row as ContestRankView;
      const replay = isReplayRow(row);

      let nickname = row.nickname;
      // 回放行昵称 / 头像以 body 快照为权威展示值，不用比赛别名覆盖
      if (!replay && contestNames[row.userId]) {
        nickname = contestNames[row.userId];
      }
      const text = GetEllipsisText(nickname, 18);

      // 回放行身份跨比赛不等价，不参与收藏：收藏按钮置为隐藏
      let starButton = null;
      if (!replay) {
        if (isUserBeStar(row.userId)) {
          starButton = (
            <t-button
              shape="circle"
              variant="text"
              class="rank-unstar-button"
              onClick={() => {
                contestStore.removeStarMember(contestId, row.userId);
                loadProgress();
              }}
              v-slots={{
                icon: () => <StarFilledIcon />,
              }}
            />
          );
        } else {
          starButton = (
            <t-button
              shape="circle"
              variant="text"
              class="rank-star-button"
              onClick={() => {
                contestStore.addStarMember(contestId, row.userId);
                loadProgress();
              }}
              v-slots={{
                icon: () => <StarIcon />,
              }}
            ></t-button>
          );
        }
      }
      const avatarUrl = GetAvatarUrl(row.username, row.email as string);
      const sourceTooltip = formatReplaySourceTooltip(row);
      return (
        <div class="rank-nickname-cell">
          <t-space>
            <t-avatar shape="round" size="32px" image={avatarUrl} hide-on-load-failed={false} />
            {replay ? (
              <t-tooltip content={sourceTooltip}>
                <span class="rank-replay-nickname">
                  <t-tag theme="warning" variant="light" size="small">
                    回放
                  </t-tag>
                  {text}
                </span>
              </t-tooltip>
            ) : (
              <t-tooltip content={nickname}>
                <t-button
                  variant="text"
                  onClick={() =>
                    router.push({
                      name: "user",
                      params: { username: row.username },
                    })
                  }
                >
                  {text}
                </t-button>
              </t-tooltip>
            )}
            {starButton}
          </t-space>
        </div>
      );
    },
  },
  {
    title: "Solved",
    colKey: "solved",
    align: "center",
    fixed: "left",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const row = data.row as ContestRankView;
      // 回放行快照选手在本场没有提交记录，不跳转本场提交列表
      if (isReplayRow(row)) {
        return <span>{row.solved}</span>;
      }
      return (
        <t-button
          variant="text"
          onClick={() =>
            router.push({
              name: "contest-judge",
              params: {
                contestId: contestId,
              },
              query: {
                username: row.username,
                status: JudgeStatus.Accept,
              },
            })
          }
        >
          {row.solved}
        </t-button>
      );
    },
  },
  {
    title: "Penalty",
    colKey: "penalty",
    align: "center",
    fixed: "left",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return getDurationText(data.row.penalty);
    },
  },
];

const listColumns = ref<ContestRankColumn[]>([]);

const dataLoading = ref(false);

let fetchRankViews = [] as ContestRank[];
let fetchVMembersViews = [] as number[];
const contestRankViews = ref<ContestRankView[]>([]);
let lastContestRankView = [] as ContestRankView[];

// 回放面板：本场已关联回放元信息（源无权的回放后端已整条剔除）
const replayList = ref<ContestReplay[]>([]);
// 本场是不是回放比赛：回放比赛自己的成绩就来自上传榜单，它的自关联行不是「关联的回放」，
// 面板整块不展示（设计文档 §5），因此也不去拉这个接口
const isReplayContest = ref(false);
// 回放启停的本地状态：key 为回放关联 ID，value 为是否展示其选手行；本期只存本地，不回写服务端
const replayVisibleMap = ref<Record<number, boolean>>({});

// 回放开关本地持久化（localStorage）：跨刷新保留偏好，不涉及账号同步
const replayToggleStorageKey = (id: number) => `contest_replay_toggles_${id}`;
const loadPersistedReplayToggles = (contestId: number): Record<number, boolean> => {
  try {
    const raw = localStorage.getItem(replayToggleStorageKey(contestId));
    if (!raw) {
      return {};
    }
    const parsed = JSON.parse(raw);
    return typeof parsed === "object" && parsed !== null ? (parsed as Record<number, boolean>) : {};
  } catch (err) {
    console.error(err);
    return {};
  }
};
const persistReplayToggles = (contestId: number, map: Record<number, boolean>) => {
  try {
    localStorage.setItem(replayToggleStorageKey(contestId), JSON.stringify(map));
  } catch (err) {
    console.error(err);
  }
};

const rowspanAndColspan = ({ col, rowIndex }: CellParams<TableRowData>) => {
  if (col.colKey === "rank") {
    let realCurrent = pagination.value.current;
    if (pagination.value.current > Math.ceil(contestRankViews.value.length / pagination.value.pageSize)) {
      realCurrent = Math.ceil(contestRankViews.value.length / pagination.value.pageSize);
    }
    const offset = pagination.value.pageSize * (realCurrent - 1);
    let rowspan = 1;
    for (let i = rowIndex + 1; offset + i < contestRankViews.value.length; i++) {
      if (contestRankViews.value[offset + i].rank === contestRankViews.value[offset + rowIndex].rank) {
        rowspan++;
      } else {
        break;
      }
    }
    return {
      rowspan: rowspan,
    };
  }
};

const progressLabelRender = (_h: unknown, { value }: { value: number }) => {
  // 转为时分秒
  return GetTimeStringBySeconds(value);
};

const createProgressTimer = () => {
  if (fetchTimer) {
    clearInterval(fetchTimer);
  }
  // 每30秒真正获取一次数据
  fetchTimer = setInterval(() => {
    if (!viewActive) {
      return;
    }
    fetchData(false);
  }, 30000);
  // 每秒更新一次数值
  if (updateProgressTimer) {
    clearInterval(updateProgressTimer);
  }
  updateProgressTimer = setInterval(() => {
    if (!viewActive) {
      return;
    }
    if (!contestStartTime) {
      return;
    }
    progressValue.value = (new Date().getTime() - contestStartTime.getTime()) / 1000;
    const progressValueRealMax = Math.min(progressValue.value, progressMax.value);
    progressValue.value = Math.min(progressValue.value, progressValueRealMax);
    loadProgress();
  }, 1000);
};

const clearProgressTimer = () => {
  if (fetchTimer) {
    clearInterval(fetchTimer);
    fetchTimer = null;
  }
  if (updateProgressTimer) {
    clearInterval(updateProgressTimer);
    updateProgressTimer = null;
  }
};

const handleSwitchAutoRefresh = async (value: boolean) => {
  autoRefresh.value = value;
  if (value) {
    await fetchData(false);
    createProgressTimer();
  } else {
    loadProgress();
    clearProgressTimer();
  }
};

const handleSwitchAutoScroll = (value: boolean) => {
  autoScroll.value = value;
  if (value) {
    startAutoScroll();
  } else {
    stopAutoScroll();
  }
};

const handleSwitchOnlyStar = () => {
  loadProgress();
  pagination.value = { ...pagination.value, current: 1 };
};

const loadProgress = () => {
  contestRankViews.value = [];
  let results = [];

  // 计算每一题的最早的ac记录
  problemFirstAcRecords = {};

  if (!contestStartTime) {
    return;
  }

  if (!fetchRankViews) {
    return;
  }

  for (let i = 0; i < fetchRankViews.length; i++) {
    const item = fetchRankViews[i];
    // 先建立对象再逐字段赋值（与 ParseProblem 的写法一致）：rank/solved/penalty 在下面统一回填
    const result = {} as ContestRankView;
    result.userId = item.inserter;
    result.username = item.inserter_username;
    result.nickname = item.inserter_nickname;
    result.email = item.inserter_email;
    // 回放行扩展字段：身份 / 徽标 / tooltip 供列渲染与行键生成
    result.isReplay = item.is_replay === true;
    result.replayId = item.replay_id;
    result.sourceTitle = item.source_title;
    result.sourceUserId = item.source_user_id;
    result.rankKey = item.rank_key;

    // 关闭的回放不渲染其选手行（本地开关，本期不回写服务端）
    if (result.isReplay && replayVisibleMap.value[result.replayId ?? 0] === false) {
      continue;
    }

    let acCount = 0;
    let penalty = 0;
    item.problems.forEach((problem: ContestRankProblem) => {
      let acDuration = -1;
      let lockCount = problem.lock || 0;
      problem.attempt = problem.attempt || 0;
      if (problem.ac) {
        let contestStartTimeGetTime = 0;
        if (contestStartTime) {
          contestStartTimeGetTime = contestStartTime.getTime();
        }
        acDuration = (new Date(problem.ac).getTime() - contestStartTimeGetTime) / 1000; // 转换为秒
        if (acDuration > progressValue.value) {
          // 如果滑倒最后并且还开着自动刷新，那么额外展示补题的提交
          if (!(autoRefresh.value && progressValue.value === progressMax.value)) {
            return;
          }
        }
        acCount++;
        penalty += acDuration;
        // 每一次尝试罚时20分钟
        penalty += problem.attempt * 20 * 60;

        // 首 AC 记录按行身份键存储（回放行与真人行键不冲突）
        const rowKey = replayRankKey(result);
        if (problemFirstAcRecords[problem.index] === undefined) {
          problemFirstAcRecords[problem.index] = {
            key: rowKey,
            ac: acDuration,
          };
        } else if (problemFirstAcRecords[problem.index].ac > acDuration) {
          problemFirstAcRecords[problem.index].key = rowKey;
          problemFirstAcRecords[problem.index].ac = acDuration;
        }
      }
      if (lockCount > 0 && lockRankDurationSeconds > 0) {
        const lockTimeSeconds = progressMax.value - lockRankDurationSeconds;
        if (progressValue.value < lockTimeSeconds) {
          lockCount = 0;
        }
      }
      const problemIndex = problem.index;
      result[`problem_${problemIndex}`] = {
        acDuration: acDuration,
        attempt: problem.attempt || 0, // 尝试次数
        lock: lockCount, // 锁定状态
      };
    });
    result.solved = acCount;
    result.penalty = penalty; // 转换为分钟
    results.push(result);
  }
  results.sort((a: ContestRankView, b: ContestRankView) => {
    if (a.solved !== b.solved) {
      return b.solved - a.solved; // 降序
    }
    if (a.penalty !== b.penalty) {
      return a.penalty - b.penalty; // 升序
    }
    // tiebreak：双真人按 userId 数值升序；含回放行时按行身份键字符串确定性兜底
    return replayRankTiebreak(a, b);
  });

  const vMembers = fetchVMembersViews;
  let rank = 0;
  let rankIncrement = 0;
  let lastAccept = -1;
  let lastPenalty = -1;
  for (let i = 0; i < results.length; i++) {
    // 回放行不参与 members_ignore：其 userId 为 source_user_id，可能与目标忽略名单成员撞号
    if (!isReplayRow(results[i]) && vMembers && vMembers.includes(results[i].userId)) {
      results[i].rank = "*";
    } else {
      rankIncrement++;
      if (results[i].solved !== lastAccept || results[i].penalty !== lastPenalty) {
        rank = rankIncrement; // 更新排名
        lastAccept = results[i].solved;
        lastPenalty = results[i].penalty;
      }
      results[i].rank = String(rank);
    }
  }

  if (onlyShowStarMembers.value) {
    results = results.filter((item) => {
      // 回放行不参与收藏，仅展示真人收藏选手
      return !isReplayRow(item) && isUserBeStar(item.userId);
    });
  }

  const rows = document.querySelectorAll("tbody tr");

  // 第一步：构建行身份键 => rect 映射
  const oldRectsMap = {} as Record<string, DOMRect>;
  lastContestRankView.forEach((row, index) => {
    const tr = rows[index];
    if (!tr) return;
    oldRectsMap[replayRankKey(row)] = tr.getBoundingClientRect();
  });

  pagination.value = { ...pagination.value, total: results.length };

  contestRankViews.value = results;

  for (let i = 0; i < contestRankViews.value.length; i++) {
    contestRankViews.value[i].index = i + 1;
  }

  lastContestRankView = [...contestRankViews.value];

  if (enableAnimation.value) {
    const newRectsMap = {} as Record<string, DOMRect>;

    const newRows = document.querySelectorAll<HTMLElement>("table tbody tr");
    contestRankViews.value.forEach((row, index) => {
      const tr = newRows[index];
      if (!tr) return;
      newRectsMap[replayRankKey(row)] = tr.getBoundingClientRect();
    });

    requestAnimationFrame(() => {
      const newRows = document.querySelectorAll<HTMLElement>("table tbody tr");
      contestRankViews.value.forEach((row, index) => {
        const newRow = newRows[index];
        const rowKey = replayRankKey(row);
        const oldRect = oldRectsMap[rowKey];
        const newRect = newRectsMap[rowKey];
        if (oldRect && newRect) {
          const dy = oldRect.top - newRect.top;
          if (dy !== 0) {
            newRow.style.transition = "none";
            newRow.style.transform = `translateY(${dy}px)`;
          }
        }
      });

      requestAnimationFrame(() => {
        const newRows = document.querySelectorAll<HTMLElement>("table tbody tr");
        newRows.forEach((row) => {
          row.style.transition = "transform 300ms ease";
          row.style.transform = "";
        });
      });
    });
  }
};

const handleProgressChange = (value: number) => {
  handleSwitchAutoRefresh(false);
  if (!contestStartTime) {
    return;
  }
  progressValue.value = value;
  const progressValueRealMax = Math.min(progressMax.value, (new Date().getTime() - contestStartTime?.getTime()) / 1000);
  progressValue.value = Math.min(progressValue.value, progressValueRealMax);
  loadProgress();
};

// 导出榜单为 Excel
const exportRankToExcel = async () => {
  if (contestRankViews.value.length === 0) {
    ShowTextTipsInfo(globalProperties, "暂无数据可导出");
    return;
  }

  // 动态导入 exceljs，仅在点击导出时加载
  const ExcelJS = (await import("exceljs")).default;

  // 创建工作簿和工作表
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet("比赛榜单");

  // 构建 Excel 表头
  const headers = ["Rank", "用户名", "昵称", "Solved", "Penalty"];

  // 问题列的 colKey 形如 problem_1：先取出字符串键，供表头与数据行共用
  // （这里用 for..of 而非 map/filter，避免实例化 tdesign 的递归列类型触发 TS2589）
  const problemKeys: string[] = [];
  for (const col of listColumns.value) {
    const colKey = col.colKey;
    if (typeof colKey === "string" && colKey.startsWith("problem_")) {
      problemKeys.push(colKey);
    }
  }
  problemKeys.forEach((problemKey) => {
    // 问题列的标题是一个函数，我们需要获取问题索引并转换为正确的标题格式
    const problemIndex = parseInt(problemKey.replace("problem_", ""));
    headers.push(GetContestProblemIndexStr(problemIndex));
  });

  // 添加表头行
  const headerRow = worksheet.addRow(headers);
  // 设置表头样式（可选）
  headerRow.font = { bold: true };
  headerRow.alignment = { vertical: "middle", horizontal: "center" };

  // 构建 Excel 数据行
  contestRankViews.value.forEach((row) => {
    // 回放行昵称以 body 快照为准，不用比赛别名覆盖
    const displayNickname = isReplayRow(row) ? row.nickname : contestNames[row.userId] || row.nickname;
    const rowData: (string | number)[] = [row.rank, row.username, displayNickname, row.solved, getDurationText(row.penalty)];

    // 添加每个问题的数据
    problemKeys.forEach((problemKey) => {
      const problem = row[problemKey];
      // problem_${index} 字段是单题统计对象；非对象（字符串/数字）与 falsy 一样输出空串
      if (problem && typeof problem === "object") {
        let text = "";
        if (problem.acDuration >= 0) {
          text = getDurationText(problem.acDuration);
        }
        if (problem.attempt > 0) {
          if (text) {
            text += " ";
          }
          text += `(-${problem.attempt})`;
        }
        if (problem.lock > 0) {
          if (text) {
            text += " ";
          }
          text += `(+${problem.lock})`;
        }
        rowData.push(text);
      } else {
        rowData.push("");
      }
    });

    worksheet.addRow(rowData);
  });

  // 设置列宽自适应（可选）
  worksheet.columns.forEach((column) => {
    let maxLength = 0;
    // exceljs 的 eachCell 声明为可选，这里按可选调用（未定义时跳过）
    column.eachCell?.((cell) => {
      const columnLength = cell.value ? cell.value.toString().length : 0;
      if (columnLength > maxLength) {
        maxLength = columnLength;
      }
    });
    column.width = maxLength < 10 ? 10 : maxLength + 2;
  });

  // 生成 Excel 文件并下载
  const fileName = `contest_rank_${contestId}_${new Date().getTime()}.xlsx`;
  const buffer = await workbook.xlsx.writeBuffer();
  saveAs(new Blob([buffer]), fileName);
};

function startAutoScroll() {
  if (scrollTimer) return; // 已在滚动中则不重复启动

  scrollTimer = setInterval(() => {
    const scrollTop = window.scrollY;
    const scrollHeight = document.documentElement.scrollHeight;
    const clientHeight = window.innerHeight;

    // 滚动到下一位置
    window.scrollTo(0, scrollTop + scrollSpeed);

    // 如果到达底部，则返回顶部
    if (scrollTop + clientHeight >= scrollHeight - 1) {
      window.scrollTo(0, 0);
    }
  }, scrollInterval);
}

function stopAutoScroll() {
  if (scrollTimer) {
    clearInterval(scrollTimer);
    scrollTimer = null;
  }
}

// 拉取本场回放面板元信息：仅用于开关展示与选手行显隐；失败不影响真人榜单。
// 回放比赛不适用（自己的成绩不叫「关联的回放」），直接留空、不打接口。
const fetchReplayPanel = async () => {
  replayList.value = [];
  replayVisibleMap.value = {};
  if (isReplayContest.value) {
    return;
  }
  try {
    const res = await GetContestReplayList(contestId);
    if (res.code === 0 && Array.isArray(res.data)) {
      replayList.value = (res.data as ContestReplayRaw[]).map((item) => ParseContestReplay(item));
      // 初始启停态：服务端停用的回放强制隐藏，本地偏好只在启用时覆盖默认（本期不回写服务端）
      const persisted = loadPersistedReplayToggles(contestId);
      replayList.value.forEach((replay) => {
        replayVisibleMap.value[replay.id] = replay.enabled ? (persisted[replay.id] ?? true) : false;
      });
    }
  } catch (err) {
    console.error(err);
  }
};

// 回放开关切换：仅本地显隐其选手行，持久化到 localStorage，不写服务端
const handleSwitchReplay = (replayId: number, visible: boolean) => {
  replayVisibleMap.value[replayId] = visible;
  persistReplayToggles(contestId, replayVisibleMap.value);
  loadProgress();
};

const fetchData = async (needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  try {
    const res = await GetContestRank(contestId);
    listColumns.value = [...listColumns1];
    fetchRankViews = [];
    fetchVMembersViews = [];
    contestRankViews.value = [];
    pagination.value = { ...pagination.value, total: 0 };
    if (res.code === 0) {
      if (!res.data.has_auth) {
        ShowTextTipsInfo(globalProperties, "您目前没有权限查看比赛排名");
        await router.push({ name: "contest-detail", params: { contestId: contestId } });
        return;
      }

      contestNames = {} as Record<number, string>;
      if (res.data.contest.members) {
        res.data.contest.members.forEach((member: { id: number; contest_name: string }) => {
          contestNames[member.id] = member.contest_name;
        });
      }

      res.data.contest.problems.sort((a: number, b: number) => a - b);
      res.data.contest.problems.forEach((problemIndex: number, _: number) => {
        listColumns.value.push({
          colKey: `problem_${problemIndex}`,
          align: "center",
          title: () => {
            return (
              <t-button
                variant="text"
                onClick={() =>
                  router.push({
                    name: "contest-problem-detail",
                    params: { contestId, problemIndex },
                  })
                }
              >
                {GetContestProblemIndexStr(problemIndex)}
              </t-button>
            );
          },
          cell: (_h: unknown, data: CellParams<TableRowData>) => {
            const problem = data.row[`problem_${problemIndex}`];
            if (!problem) {
              return "";
            }
            let text = "";
            if (problem.acDuration >= 0) {
              text = getDurationText(problem.acDuration);
            }
            if (problem.attempt > 0) {
              if (text) {
                text += " ";
              }
              text += `(-${problem.attempt})`;
            }
            if (problem.lock > 0) {
              if (text) {
                text += " ";
              }
              text += `(+${problem.lock})`;
            }
            return <span>{text}</span>;
          },
          attrs: (data: CellParams<TableRowData>) => {
            const problem = data.row[`problem_${problemIndex}`];
            if (!problem) {
              return {};
            }
            if (problem.acDuration >= 0) {
              const firstAcRecord = problemFirstAcRecords[problemIndex];
              if (firstAcRecord !== undefined) {
                const row = data.row as ContestRankView;
                if (firstAcRecord.key === replayRankKey(row)) {
                  return {
                    style: {
                      backgroundColor: "rgba(65,155,5,0.5)",
                    },
                  };
                }
              }
              // 比赛未开始/结束时（理论上不会发生）取不到时间差，此时按「非补题」处理
              if (contestEndTime && contestStartTime && problem.acDuration > (contestEndTime.getTime() - contestStartTime.getTime()) / 1000) {
                return {
                  style: {
                    backgroundColor: "rgba(100,255,100,0.5)",
                  },
                };
              }
              return {
                style: {
                  backgroundColor: "rgba(130,255,30,0.5)",
                },
              };
            }
            if (problem.lock > 0) {
              return {
                style: {
                  backgroundColor: "rgb(255,180,50,0.5)",
                },
              };
            }
            if (problem.attempt > 0) {
              return {
                style: {
                  backgroundColor: "rgba(255,120,120,0.5)",
                },
              };
            }
            return {};
          },
        });
      });
      const contest = res.data.contest;
      contestStartTime = new Date(contest.start_time);
      contestEndTime = new Date(contest.end_time);
      fetchRankViews = res.data.ranks as ContestRank[];
      fetchVMembersViews = res.data.v_members || [];

      // 回放比赛标识：用于隐藏「关联的回放」面板（榜单行本身照常展示上传榜单的成绩）
      isReplayContest.value = contest.is_replay === true;

      await fetchReplayPanel();

      progressMax.value = Math.floor((contestEndTime.getTime() - contestStartTime.getTime()) / 1000);
      const lockRankMarks: Record<number, string | TNodeReturnValue> = {
        0: "0",
        [Math.floor(progressMax.value / 2)]: GetTimeStringBySeconds(Math.floor(progressMax.value / 2)),
        [progressMax.value]: GetTimeStringBySeconds(progressMax.value),
      };
      progressMarks.value = lockRankMarks;
      lockRankDurationSeconds = GetSecondFromDuration(contest.lock_rank_duration || 0);
      if (res.data.is_locked && lockRankDurationSeconds > 0) {
        const lockTimeSeconds = Math.max(0, progressMax.value - lockRankDurationSeconds);
        progressMarks.value[lockTimeSeconds] = <span style="color: #0052d9">锁榜({GetTimeStringBySeconds(lockTimeSeconds)})</span>;
      }

      progressValue.value = Math.floor((new Date().getTime() - contestStartTime.getTime()) / 1000);
      const progressValueRealMax = Math.min(progressValue.value, progressMax.value);
      progressValue.value = Math.min(progressValue.value, progressValueRealMax);

      autoRefresh.value = true;
      createProgressTimer();

      loadProgress();
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
  }
};

// 初始化分页信息
onMounted(async () => {
  viewActive = true;

  watchHandle = watch(
    () => route.query,
    async (newQuery: LocationQuery) => {
      if (Array.isArray(route.params.contestId)) {
        contestId = Number(route.params.contestId[0]);
      } else {
        contestId = Number(route.params.contestId);
      }
      if (!contestId) {
        await router.push({ name: "contest" });
        return;
      }
      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
      currentPage = queryPage;
      currentPageSize = queryPageSize;
      pagination.value = { ...pagination.value, current: currentPage, pageSize: currentPageSize };
      await fetchData(true);
    },
    { immediate: true }
  );
});

onBeforeUnmount(() => {
  viewActive = false;
  if (watchHandle) {
    watchHandle();
  }
  clearProgressTimer();
  stopAutoScroll();
});
</script>

<template>
  <t-row>
    <t-card style="margin: 10px; width: 100%">
      <div class="rank-header-area">
        <div class="rank-time-text">榜单时间 {{ GetTimeStringBySeconds(progressValue) }}</div>
        <div class="rank-switches">
          <t-space :class="isMobile ? 'rank-switches-mobile' : ''" :size="isMobile ? 'small' : 'medium'">
            <t-switch v-model="onlyShowStarMembers" size="large" @change="handleSwitchOnlyStar">
              <template #label="slotProps">{{ slotProps.value ? "仅展示收藏" : "未过滤收藏" }}</template>
            </t-switch>
            <t-switch v-model="enableAnimation" size="large">
              <template #label="slotProps">{{ slotProps.value ? "开启动画" : "关闭动画" }}</template>
            </t-switch>
            <t-switch v-model="autoRefresh" size="large" @change="handleSwitchAutoRefresh">
              <template #label="slotProps">{{ slotProps.value ? "自动刷新" : "关闭刷新" }}</template>
            </t-switch>
            <t-switch v-model="autoScroll" size="large" @change="handleSwitchAutoScroll">
              <template #label="slotProps">{{ slotProps.value ? "自动滚动" : "关闭滚动" }}</template>
            </t-switch>
            <t-button size="small" variant="outline" @click="exportRankToExcel">导出榜单</t-button>
          </t-space>
        </div>
        <div v-if="replayList.length > 0 && !isReplayContest" class="rank-replay-panel">
          <t-space :class="isMobile ? 'rank-switches-mobile' : ''" size="medium" wrap>
            <t-tooltip v-for="replay in replayList" :key="replay.id" :content="replay.sourceTitle ? `回放自：${replay.sourceTitle}` : ''">
              <t-switch :value="replayVisibleMap[replay.id]" size="large" @change="(value: boolean) => handleSwitchReplay(replay.id, value)">
                <template #label>
                  <span class="rank-replay-label">
                    回放 {{ replay.title }} · {{ replay.playerCount }} 人
                    <t-tag v-if="replay.isAlias" theme="warning" variant="light" size="small">别名</t-tag>
                    <t-tag v-if="!replay.problemMatched" theme="danger" variant="light" size="small">题目已变更</t-tag>
                  </span>
                </template>
              </t-switch>
            </t-tooltip>
          </t-space>
        </div>
        <t-slider
          v-model="progressValue"
          :marks="progressMarks"
          :max="progressMax"
          :label="progressLabelRender"
          :tooltip-props="{ placement: 'top' }"
          @change-end="handleProgressChange"
        />
      </div>
      <div class="table-scroll-wrapper">
        <t-table
          :data="contestRankViews"
          :columns="listColumns"
          row-key="index"
          vertical-align="middle"
          :bordered="true"
          :hover="true"
          table-layout="auto"
          :rowspan-and-colspan="rowspanAndColspan"
          :loading="dataLoading"
          class="dida-contest-rank-table"
          :pagination="pagination"
          @page-change="onPageChange"
        />
      </div>
    </t-card>
  </t-row>
</template>

